use core::fmt;

use crate::hash::XOFReader;
use crate::secret::Zeroize;

/// The permutation Keccak-f\[1600\] (FIPS 202 section 3), on 25 lanes of 64
/// bits indexed `x + 5 * y`.
pub struct KeccakF1600;

impl KeccakF1600 {
    pub const ROUNDS: usize = 24;
    /// The round constants of the step ι, generated by Algorithm 5 of section 3.2.5.
    pub const ROUND_CONSTANTS: [u64; 24] = KeccakF1600::round_constants();
    /// The rotation offsets of the step ρ (section 3.2.2), indexed `x + 5 * y`.
    pub const ROTATIONS: [u32; 25] = KeccakF1600::rotations();

    /// The bit `rc(t)` of Algorithm 5: the output of an LFSR over GF(2)
    /// with the polynomial x^8 + x^6 + x^5 + x^4 + 1.
    pub const fn rc(t: usize) -> u64 {
        if t.is_multiple_of(255) {
            return 1;
        }
        // Bit i of `r` is R[i]; initially R = 10000000, that is R[0] = 1.
        let mut r: u16 = 1;
        let mut step = 0;
        while step < t % 255 {
            // R = 0 || R, then R[0], R[4], R[5] and R[6] ^= R[8], then Trunc8.
            r <<= 1;
            if r & 0x100 != 0 {
                r ^= 0x171;
            }
            step += 1;
        }
        (r & 1) as u64
    }

    pub const fn round_constants() -> [u64; 24] {
        let mut constants = [0u64; 24];
        let mut round = 0;
        while round < 24 {
            let mut j = 0;
            while j <= 6 {
                constants[round] |= KeccakF1600::rc(j + 7 * round) << ((1 << j) - 1);
                j += 1;
            }
            round += 1;
        }
        constants
    }

    pub const fn rotations() -> [u32; 25] {
        let mut offsets = [0u32; 25];
        let (mut x, mut y) = (1, 0);
        let mut t = 0;
        while t < 24 {
            offsets[x + 5 * y] = (((t + 1) * (t + 2) / 2) % 64) as u32;
            let next = (2 * x + 3 * y) % 5;
            x = y;
            y = next;
            t += 1;
        }
        offsets
    }

    /// Applies the 24 rounds to `state`.
    pub fn permute(state: &mut [u64; 25]) {
        let mut columns = [0u64; 5];
        let mut moved = [0u64; 25];
        for round_constant in KeccakF1600::ROUND_CONSTANTS {
            // θ
            for (x, column) in columns.iter_mut().enumerate() {
                *column = state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20];
            }
            for x in 0..5 {
                let difference = columns[(x + 4) % 5] ^ columns[(x + 1) % 5].rotate_left(1);
                for y in 0..5 {
                    state[x + 5 * y] ^= difference;
                }
            }
            // ρ and π
            for x in 0..5 {
                for y in 0..5 {
                    moved[y + 5 * ((2 * x + 3 * y) % 5)] =
                        state[x + 5 * y].rotate_left(KeccakF1600::ROTATIONS[x + 5 * y]);
                }
            }
            // χ
            for y in 0..5 {
                for x in 0..5 {
                    state[x + 5 * y] = moved[x + 5 * y] ^ (!moved[(x + 1) % 5 + 5 * y] & moved[(x + 2) % 5 + 5 * y]);
                }
            }
            // ι
            state[0] ^= round_constant;
        }
        columns.zeroize();
        moved.zeroize();
    }
}

/// The sponge construction over Keccak-f\[1600\] (FIPS 202 section 4) with a
/// rate of `RATE` bytes and the domain separation `suffix`: the bits that
/// follow the message before the `pad10*1` padding, written as a byte whose
/// lowest bits come first and which ends with the first padding bit (`0x06`
/// for SHA-3, `0x1F` for SHAKE, `0x04` for cSHAKE, `0x01` for Keccak).
///
/// It absorbs until [`Sponge::pad`] and squeezes afterwards; it is the
/// [`XOFReader`] of the extendable-output functions.
#[derive(Clone)]
pub struct Sponge<const RATE: usize> {
    state: [u64; 25],
    position: usize,
    suffix: u8,
    squeezing: bool,
}

impl<const RATE: usize> Sponge<RATE> {
    pub const fn new(suffix: u8) -> Sponge<RATE> {
        const { assert!(RATE > 0 && RATE < 200 && RATE.is_multiple_of(8), "the rate is a whole number of lanes") };
        Sponge { state: [0; 25], position: 0, suffix, squeezing: false }
    }

    pub fn is_squeezing(&self) -> bool {
        self.squeezing
    }

    /// XORs `byte` into byte `index` of the state.
    pub fn xor_byte(&mut self, index: usize, byte: u8) {
        self.state[index / 8] ^= (byte as u64) << (8 * (index % 8));
    }

    /// Adds `data` to the input; does nothing once squeezing.
    pub fn absorb(&mut self, data: &[u8]) {
        if self.squeezing {
            return;
        }
        let mut data = data;
        // Whole lanes go in at once when the position is lane-aligned.
        while !data.is_empty() {
            if self.position.is_multiple_of(8)
                && self.position + 8 <= RATE
                && let Some((lane, rest)) = data.split_first_chunk::<8>()
            {
                self.state[self.position / 8] ^= u64::from_le_bytes(*lane);
                self.position += 8;
                data = rest;
            } else {
                self.xor_byte(self.position, data[0]);
                self.position += 1;
                data = &data[1..];
            }
            if self.position == RATE {
                KeccakF1600::permute(&mut self.state);
                self.position = 0;
            }
        }
    }

    /// Absorbs zeros up to the end of the current block, as `bytepad` of SP
    /// 800-185 does; nothing if the position is at the start of a block.
    pub fn fill_block(&mut self) {
        if !self.squeezing && self.position != 0 {
            KeccakF1600::permute(&mut self.state);
            self.position = 0;
        }
    }

    /// Ends the input: the suffix and the padding, then the first permutation.
    pub fn pad(&mut self) {
        if self.squeezing {
            return;
        }
        self.xor_byte(self.position, self.suffix);
        self.xor_byte(RATE - 1, 0x80);
        KeccakF1600::permute(&mut self.state);
        self.position = 0;
        self.squeezing = true;
    }

    /// Writes the next `out.len()` bytes of output, padding first if needed.
    pub fn squeeze(&mut self, out: &mut [u8]) {
        self.pad();
        for byte in out.iter_mut() {
            if self.position == RATE {
                KeccakF1600::permute(&mut self.state);
                self.position = 0;
            }
            *byte = (self.state[self.position / 8] >> (8 * (self.position % 8))) as u8;
            self.position += 1;
        }
    }

    /// Returns to the empty input with the same suffix.
    pub fn reset(&mut self) {
        self.zeroize();
    }
}

impl<const RATE: usize> XOFReader for Sponge<RATE> {
    fn read(&mut self, out: &mut [u8]) {
        self.squeeze(out);
    }
}

impl<const RATE: usize> Zeroize for Sponge<RATE> {
    /// Clears the state and the position; the suffix is kept.
    fn zeroize(&mut self) {
        self.state.zeroize();
        self.position.zeroize();
        self.squeezing.zeroize();
    }
}

impl<const RATE: usize> Drop for Sponge<RATE> {
    fn drop(&mut self) {
        self.zeroize();
    }
}

impl<const RATE: usize> fmt::Debug for Sponge<RATE> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "Sponge<{RATE}>(..)")
    }
}
